    elif mode == 1:
        # sorted ascending
        a = sorted(a)
    s = draw(st.one_of(
        st.integers(1, 40),
        st.integers(1, 6),
        st.sampled_from([sum(a), sum(a) + 1, max(1, sum(a) - 1)]),
    ))
    return f"{n} {s}\n{' '.join(map(str, a))}\n"

